# Deutsche Uebersetzungen: Param/Item/KeyItem.csv (75 Name/Beschreibung-Paare)

_PATH = "Param/Item/KeyItem.csv"
_PAIRS = [
    ("Öltropfen", "Ein verfluchtes Werkzeug aus Öl. Aktiviere es beim Erkunden\nmit ~AburadamaButton~, bedenke aber, dass seine Kraft mit der Zeit\nnachlässt. Mit ~AburadamaButton~ steckst du es wieder weg."),
    ("Zunehmender Mondsstein", "Dies scheint ein Teil eines Schlüssels zu sein, der ein\nSteintor in der Auberginen-Grube öffnet."),
    ("Abnehmender Mondsstein", "Dies scheint ein Teil eines Schlüssels zu sein, der ein\nSteintor in der Auberginen-Grube öffnet."),
    ("Kirin-Erde", "Ein dicker Erdklumpen, der geradezu von der Kraft\nder Erdenergie glüht. Kann als Material für Lady\nKokorowas Schwarze Schmiede verwendet werden."),
    ("Schriftrolle: Kampf 1", "LP - Fehlt dir Gesundheit, handlungsunfähig.\nSättigung - Nimmt mit der Zeit ab, danach enden Essenseffekte.\nSP - Technikpunkte für Kampf- und Gewandtechniken."),
    ("Schriftrolle: Kampf 2", "Stärke - Die Kraft deiner körperlichen Angriffe.\nVitalität - Dein Widerstand gegen Feindangriffe.\nMagie - Die Kraft von Kampftechniken und einiger Gewandtechniken."),
    ("Schriftrolle: Kampf 3", "Glück - Gewährt vielfältige positive Effekte.\nAppetit - Die Kraft deiner aktiven Essenseffekte."),
    ("Schriftrolle: Waffenangriffe 1", "~AttackWButton~ beginnt einen schnellen Angriff mit Einhandwaffen.\n~AttackSButton~ beginnt einen schweren Angriff mit der Zweihandwaffe.\nLetztere kann Feinde zuwerfen - setze sie an mächtigen Gegnern ein."),
    ("Schriftrolle: Waffenangriffe 2", "Drücke ~AttackWButton~ und/oder ~AttackSButton~ nacheinander, um eine\nKombo auszulösen. Bewege ~LStick~ gleichzeitig, um die\nAngriffsrichtung zu ändern."),
    ("Schriftrolle: Kampftechniken", "Mit ~SkillButton~ führst du Kampftechniken gegen SP aus, die sich\nmit der Zeit automatisch auffüllen. Lege Techniken im ~PauseButton~-\nMenü für verschiedene Richtungen fest und ändere sie dort."),
    ("Schriftrolle: Griff", "Schiebe ~LStick~ in die gewünschte Richtung und drücke dann\n~ClothButton~, um dein Göttliches Gewand auszustrecken. Erfasst es\nGelände, fliegst du im Nu dorthin."),
    ("Schriftrolle: Göttliches Gewand 1", "Schiebe ~LStick~ und ~ClothButton~, um dein Göttliches Gewand auszustrecken.\nTrifft es einen Feind, schwingst du geschickt hinter ihn.\nSo kannst du Angriffe ausweichen und Gegner überraschen."),
    ("Schriftrolle: Göttliches Gewand 2", "Halte ~ClothButton~ gedrückt, während das Gewand an einem Feind hängt,\nund schiebe dann ~LStick~, um eine Gewandtechnik auszuführen.\nVorsicht: Der Gegner muss umgeworfen sein, damit die Technik greift.\nGewandtechniken legst du im ~PauseButton~-Menü fest."),
    ("Schriftrolle: Sprinten", "Schiebe ~LStick~ ~Left~ ~Left~ oder ~Right~ ~Right~ schnell hintereinander,\num in diese Richtung zu sprinten. Damit gleitest du sicher\nan Angriffen oder Feinden vorbei."),
    ("Schriftrolle: Parieren", "Schiebe ~Left~ oder ~Right~ genau dann gegen einen angreifenden Feind,\nwenn der Einschlag kommt, um ihn zu parieren. Der Feind wankt,\nsenkt den Schutz und wird anfällig für einen Gegenstoß."),
    ("Schriftrolle: Aufprall", "Lass einen Feind in einen anderen krachen, um beiden\ngroßen Schaden zuzufügen. Wer diese Technik beherrscht,\nverbessert sein Kampfkönnen enorm."),
    ("Schriftrolle: Aufprall-Kombos", "Treffe einen abprallenden Feind, bevor er den Boden erreicht,\nund schleudere ihn erneut in andere Feinde - das löst eine\nmächtige Aufprall-Kombo aus! Schöner geht es nicht."),
    ("Schriftrolle: Rückenangriffe", "Um noch mehr Schaden zu verursachen, schlage einen Gegner\nvon hinten. Nicht jeder Feind reagiert darauf, doch die meisten\nhaben einen verwundbaren Rücken."),
    ("Schriftrolle: Attribute 1", "Angriffe besitzen eines von vier Attributen: Schlag, Schnitt,\nStich und Magie. Das Attribut eines Angriffs hängt von Waffe\nund Technik ab. Manche Attribute sind gegen manche Feinde\nwirksamer als andere."),
    ("Schriftrolle: Attribute 2", "Verschiedene Feinde sind gegen verschiedene Attribute anfällig.\nEine orangefarbene Schadenanzeige heißt: der Angriff wirkt.\nEine rote Schadenanzeige heißt: er wirkt besonders stark.\nEine blaue Schadenanzeige heißt: er wirkt nicht."),
    ("Schriftrolle: Kritische Treffer", "Angriffe können einen kritischen Treffer auslösen und damit\nverdoppeln. Beim Erleiden von Schaden kann Schutzschild\nausgelöst werden, der den erlittenen Schaden um 30% senkt.\nJe höher dein Glück, desto häufiger treten diese Effekte auf."),
    ("Schriftrolle: Einbruch der Nacht", "Dämonen sind nachts stärker, also sei vorsichtig bei Sonnenuntergang.\nEs gibt jedoch Schätze, die nur nächtliche Dämonen fallen lassen.\nDie fünf Elementarmaterialien etwa findet man nur bei Nacht.\nStähle deine Kraft, bevor du dich in die Dunkelheit wagst."),
    ("Schriftrolle: Erkundung", "Wenn du nicht weißt, wohin, versuche, deine Erkundungsstufe\nzu erhöhen. Erkundungsziele in einzelnen Gebieten steigern\ndeine Gesamterkundungsstufe und eröffnen neue Wege."),
    ("Schriftrolle: Verborgene Kräfte", "Beherrschst du ein Stück Ausrüstung, wird seine verborgene\nKraft freigesetzt und gewährt verschiedene Effekte. Die\nBedingungen dafür variieren von Gegenstand zu Gegenstand - untersuche\njede Ausrüstung genau."),
    ("Schriftrolle: Geistzweige", "Geistzweige sind Bündel spiritueller Energie, die verborgene\nKräfte enthalten und auf Ausrüstung angewendet werden können.\nDurch Sammeln mehren sich deine Kräfte als Erntegöttin auf\ndem Feld und als Kriegsgöttin auf dem Schlachtfeld."),
    ("Schriftrolle: Ackerbau", "Die Kraft einer Erntegöttin hängt mit der Stärke ihrer Früchte\nzusammen. Ertrag = LP, Geschmack = Stärke, Härte = Vitalität,\nAroma = Magie, Aussehen = Glück, Klebrigkeit = Appetit."),
    ("Schriftrolle: Bodennährstoffe", "Reis nimmt beim Wachsen Nährstoffe aus dem Boden auf.\nDie Nährstoffe nehmen entsprechend ab und erschöpfen sich\nschließlich vollständig. Ohne Nährstoffe bleibt sein\nWachstum zurück."),
    ("Schriftrolle: Dünger 1", "Um an Dünger zu gelangen, wirf Mist aus der Grube in die\nDüngergrube und lasse ihn dort einen halben Tag ruhen. Auf dem\nFeld ausgebracht, steigt der Nährstoffgehalt sofort."),
    ("Schriftrolle: Dünger 2", "Nachts wächst der Reis langsamer, weshalb sich der Nährstoff-\ngehalt im Boden kaum verändert. Der Reis beginnt mit Sonnenauf-\nzuwachsen - gewöhne dir an, gleich nach dem Aufwachen zu düngen."),
    ("Schriftrolle: Schösslinge", "Kurz nach dem Pflanzen tritt der Reis in die Schösslingsphase,\ndie den Ertrag steigert. Diese Phase hat drei Stufen.\nEine Erntegöttin erkennt die Stufe am Blick ins Feld."),
    ("Schriftrolle: Entwässerung", "In der dritten Schösslingsphase entwässere das gesamte Feld,\num den Boden auszutrocknen. Die Entwässerung verhindert\nübermäßige Schösslinge, die den Reis nur schwächen."),
    ("Schriftrolle: Bewässerung 1", "Reis braucht Wasser und Sonnenlicht zum Wachsen. Erziele eine\ngrößere Ernte, indem du ihn flach hältst, bis er Wurzeln schlägt,\nund ihn dann in tieferem Wasser wachsen lässt. Überschüssiges\nWasser im Zeitverlauf verhindert Überwuchern."),
    ("Schriftrolle: Bewässerung 2", "Die Wassermenge beeinflusst die Temperatur. Flaches Wasser\nnimmt rasch die Lufttemperatur an, tiefes oder fließendes\nwasser behält seine Temperatur. Extreme Hitze oder Kälte schadet\ndem Reis, also muss der Wasserstand angepasst werden."),
    ("Schriftrolle: Wetter", "Dem Reis schadet es, wenn zu lange sonnige oder regnerische\nTage anhalten; doch Gebet und ein Bernsteinopfer an Lady\nKamuhitsuki können das Wetter ändern. Das alltägliche Wetter\nim Blick zu behalten ist entscheidend für hervorragenden Reis."),
    ("Schriftrolle: Salz und Schaden", "Salz kann nicht nur als Sortierhilfe, sondern auch als Dünger\ngenutzt werden. Es macht den Reis widerstandsfähiger gegen\nKrankheiten, doch zu viel schadet der Ernte. Alles mit Maß,\nwie man so schön sagt."),
    ("Schriftrolle: Frühdüngung", "Bringe vor dem Umgraben Dünger aus, um die Qualität der\nReisernte zu steigern. Schade, dass man dafür die Grube\nbesuchen muss..."),
    ("Schriftrolle: Nützliche Tierwelt", "Manche Kreaturen fressen Schädlinge, die dem Reis schaden.\nFindest du im Bergpass Spinnen, Schnecken oder Frösche,\nfang sie und setze sie auf deinem Feld aus."),
    ("Schriftrolle: Enten", "Bringst du Enten aufs Feld, während der Reis wächst, fressen\nsie Unkraut und Schädlinge. Sobald der Reis jedoch groß genug\nist, wollen sie stattdessen die Früchte fressen. Bleib wachsam,\num zu wissen, wann du sie entfernen solltest."),
    ("Die Kunst des Reisertrags", "Dies ist eine der Feldschriften der Lady Toyohana!\nHat sie sie verfasst, während sie in der Hauptstadt lebte?\nEs geht darum, den Ertrag möglichst zu steigern."),
    ("Schriftrolle: Frühlingsertrag", " - Sortiere den Reis leicht.\n - Säe die Samen dicht in die Setzlingskiste.\n - Pflanze viele Setzlinge, ohne sie zu dicht zu setzen."),
    ("Schriftrolle: Sommerertrag", " - Gib Körnerdünger, bis die Ähren keimen.\n - Trockne die Pflanzen in der Hochsommerzeit.\n - Nach dem Ährenkeimen Blattdünger ausbringen.\n - Lasse die Pflanzen beim Reifen in tiefem Wasser stehen."),
    ("Schriftrolle: Herbstertrag", " - Sind sie reif, trockne sie vor der Ernte so gut wie möglich.\n - Nicht zu lange, aber auch nicht zu kurz trocknen lassen."),
    ("Die Kunst des kräftigen Reises", "Dies ist eine der Feldschriften der Lady Toyohana!\nHat sie sie verfasst, während sie in der Hauptstadt lebte?\nEs geht um die Verbesserung von Geschmack, Klebrigkeit und Härte."),
    ("Schriftrolle: Frühling", " - Sortiere den Reis gründlich.\n - Säe die Samen spärlich in die Setzlingskiste.\n - Pflanze sie weit auseinander."),
    ("Schriftrolle: Sommer", " - Gib Körnerdünger, bis die Ähren keimen.\n - Nach dem Keimen sparsam Blattdünger ausbringen.\n - Lasse die Pflanzen beim Reifen in flachem Wasser stehen."),
    ("Schriftrolle: Herbst", " - Ernte an einem trockenen, sonnigen Tag.\n - Poliere sie, wenn es kühl ist."),
    ("Die Kunst des schönen Reises", "Dies ist eine der Feldschriften der Lady Toyohana!\nHat sie sie verfasst, während sie in der Hauptstadt lebte?\nEs geht um die Verbesserung des Aussehens."),
    ("Schriftrolle: Frühling (Aussehen)", " - Verzichte auf die Frühdüngung.\n - Sortiere mit Schlamm und säe die Samen spärlich ein.\n - Pflanze die Samen weit auseinander."),
    ("Schriftrolle: Sommer (Aussehen)", " - Halte den Reis in tiefem Wasser und setze Enten ein.\n - Trockne sie nur kurze Zeit.\n - Nach dem Ährenkeimen beide Tore öffnen.\n - Lasse die Pflanzen in fließendem Wasser reifen."),
    ("Schriftrolle: Herbst (Aussehen)", " - Ernte früh in der Saison.\n - Poliere den Reis, wenn es kühl ist.\n - Stelle entweder Braun- oder Weißreis her."),
    ("Die Kunst des aromatischen Reises", "Dies ist eine der Feldschriften der Lady Toyohana!\nHat sie sie verfasst, während sie in der Hauptstadt lebte?\nEs geht um die Verbesserung des Aromas."),
    ("Schriftrolle: Frühling (Aroma)", " - Sortiere den Reis gründlich.\n - Säe die Samen spärlich in die Setzlingskiste.\n - Pflanze sie weit auseinander."),
    ("Schriftrolle: Sommer (Aroma)", " - Ziehe sie in flachem Wasser, außer beim Trocknen.\n - Sorge dafür, dass die Temperatur nicht zu sehr steigt."),
    ("Schriftrolle: Herbst (Aroma)", " - Ernte früh in der Saison.\n - Lasse ihn als Braunreis, um das Aroma zu maximieren."),
    ("Die Kunst der Feldpflege", "Dies ist eine der Feldschriften der Lady Toyohana!\nHat sie sie verfasst, während sie in der Hauptstadt lebte?\nEs geht um den Umgang mit verschiedenen Schädlingen."),
    ("Schriftrolle: Schädlinge 1", " - Gerade Schnellläuferlarven: Schmetterlingslarven, die Blätter\n   verschlingen. Sie mindern den Ertrag bei der Ernte.\n - Stinkwanzen: Insekten, die an den Reisähren saugen.\n   Sie erhöhen die Anfälligkeit für Lochfleckenkrankheit."),
    ("Schriftrolle: Schädlinge 2", " - Zikaden: geflügelte Insekten, die den Reisertrag mindern.\n   Sie erhöhen die Anfälligkeit für viele Krankheiten.\n - Heuschrecken: geflügelte Insekten, die den Reisertrag mindern."),
    ("Schriftrolle: Schädlingsprävention", "Viele Insekten mögen Unkraut. Wenn du täglich jätest,\nhältst du auch verschiedene Schädlinge fern. Beeilst du\ndich, nimm stattdessen insektenabweisenden Dünger."),
    ("Die Kunst des Jätens", "Dies ist eine der Feldschriften der Lady Toyohana!\nHat sie sie verfasst, während sie in der Hauptstadt lebte?\nEs geht um den Umgang mit Unkraut auf dem Feld."),
    ("Schriftrolle: Unkraut 1", " - Algen: Unkraut im Wasser, das den Reis verwelken lässt.\n - Hühnerhirse: sieht aus wie Reis und gedeiht in gepflegten\n   Feldern. Sie bringt mehrere Krankheiten mit sich.\n - Laichkraut: ein kleines, aber stark wachsendes Unkraut,\ndas Nährstoffe stiehlt."),
    ("Schriftrolle: Unkraut 2", " - Sumpschneide: wächst das ganze Jahr über und kehrt nach dem\n   Ziehen rasch zurück. Bekannt dafür, den Reis welken zu lassen.\n - Zypergras der Flachwatten: wächst in wasserreichen Feldern\n   und stiehlt Nährstoffe."),
    ("Schriftrolle: Unkrautprävention", "Die meisten Unkräuter lassen sich von Hand ziehen, doch das ist\nnur eine Notlösung. Sorgfältiges Umgraben verhindert ihr\nWachsen besser. Wasserliebendes Unkraut stirbt, wenn du das\nFeld zeitweise entwässerst."),
    ("Die Kunst der Fruchtpflege", "Dies ist eine der Feldschriften der Lady Toyohana!\nHat sie sie verfasst, während sie in der Hauptstadt lebte?\nEs geht um den Umgang mit Reiskrankheiten."),
    ("Schriftrolle: Reiskrankheiten 1", " - Kümmerlich: wenn Halme mangels Sonnenlicht lang und dünn\n   werden.\n - Unterentwickelt: wenn die Ähren wegen zu weniger Nährstoffe\n   nicht reifen.\n - Umgefallen: wenn der Reis durch schwache Halme oder\n   starken Wind umfällt."),
    ("Schriftrolle: Reiskrankheiten 2", " - Salzschaden: wenn Setzlinge oder Pflanzen durch zu viel\n   Salz falsch wachsen.\n - Hitzeschaden: wenn der Reis durch hohe Boden- oder\n   Wassertemperatur falsch wächst.\n - Übermaß: wenn zu viel Reis wächst und Nährstoffe fehlen."),
    ("Schriftrolle: Reiskrankheiten 3", " - Trüber Reis: milchig-weißer, noch nicht ganz reifer Reis.\n - Gebrochener Reis: Reis, der beim Polieren Risse bekam."),
    ("Schriftrolle: Reiskrankheiten 4", " - Reisbrand: eine durch Schimmel verursachte Krankheit,\ndie die Qualität mindert.\n - Reis-Streifenkrankheit: durch Insekten oder Unkraut über-\n   tragen. Hängt mit kümmerlichen, unterentwickelten Halmen zusammen.\n - Rußtau: eine durch Insekten übertragene Fleckenkrankheit,\ndie das Wachstum hemmt."),
    ("Schriftrolle: Reiskrankheiten 5", " - Wanzenbrand: eine durch Insekten übertragene Krankheit.\n   Sie trocknet den Reis aus und senkt die Qualität.\n - Lochfleckenkrankheit: eine durch Insekten übertragene\n   Krankheit. Sie hinterlässt Flecken und senkt die Qualität stark.\n - Bakanae-Krankheit: eine Schimmelerkrankung, die zum\n   Welken führt."),
    ("Schriftrolle: Reis-Heilmittel", "Um eine Reiskrankheit zu heilen, muss man erst ihre Ursache\nkennen. Belebende Mittel helfen geschwächtem Reis, mindernde\nMittel dämpfen Übermaß, vertilgende Mittel helfen gegen Schädlinge\nund Schimmel. Mische sie unter den ausgebrachten Dünger,\num deine Pflanzen gesund zu halten."),
    ("Schriftrolle: Natürliche Heilmittel", " - Geröstete Eicheln: Eicheln (5).\n - Drogenfleisch: Fleisch (3, jede Sorte).\n - Getrockneter Kochreis (4 beliebige davon): Reis (jede Sorte),\n   Weizen, Hirse, Sanwa-Hirse."),
    ("Schriftrolle: einfache Rezepte", " - Gebratener Keiler: Keilerfleisch (2).\n - Gekochter Reis: Weißreis (3), Salz und Alkohol (jede Sorte).\n - Getrockneter Lachs: Lachs und Alkohol (jede Sorte)."),
    ("Schriftrolle: Kampfküche", " - Zoni: Gemüse (jede Sorte), Mochi, Suppenbrühe, Sojasauce\n   und Alkohol (jede Sorte).\n - Senbei: Mochi, Sojasauce und Alkohol (jede Sorte).\n - Kenpin: Weizen, Sesam und Zucker."),
    ("Schriftrolle: Schutzgerichte", " - Eingelegte getrocknete Pflaume (Giftabwehr): Pflaume und Salz.\n - Gekochter Tofu (Wasserabwehr): Tofu, Kombu-Alge und Quellwasser.\n - Somen (Feuerabwehr): Weizen (2), Salz und Öl."),
    ("Schriftrolle: Würzmittel", " - Miso: Malz (2), Bohnen (2) und Salz (2).\n - Sojasauce: Weizen, Bohne, Salz und Malz (2).\n - Alkohol: beginne mit Reis, Malz und Würzmittel."),
    ("Schriftrolle: Ventania-Küche", " - Pannenkoek: Weizen (3), Käse, geräuchertes Schweinefleisch\n   und Eier (3).\n - Hutspot: Kartoffeln (3), Wurzelfrüchte, Zwiebel und Salz.\n - Bier: Reis (jede Sorte), Weizen, Mais und berühmtes Wasser."),
]

assert len(_PAIRS) == 75, f"erwartet 75, gefunden {len(_PAIRS)}"

DE_KEYITEM = {}
for _i, (_n, _c) in enumerate(_PAIRS, 1):
    DE_KEYITEM[(_PATH, f"NameEn#{_i}")] = _n
    DE_KEYITEM[(_PATH, f"CommentEn#{_i}")] = _c
